// reverse maps (value -> name) for diagnostics / unknown handling
function invert(obj) {
	const out = {};
	for (const k of Object.keys(obj)) out[obj[k]] = k;
	return out;
}
export const TAG_NAME_BY_VALUE = invert(ECTagName);
export const OP_CODE_BY_VALUE = invert(ECOpCode);
export const TAG_TYPE_BY_VALUE = invert(ECTagType);

/** Unknown tag names map to EC_TAG_UNKNOWN (aMule may send tags we don't model). */
export function tagNameFromValue(value) {
	return TAG_NAME_BY_VALUE[value] !== undefined ? value : ECTagName.EC_TAG_UNKNOWN;
}
/** Unknown tag types map to EC_TAGTYPE_UNKNOWN. */
export function tagTypeFromValue(value) {
	return TAG_TYPE_BY_VALUE[value] !== undefined ? value : ECTagType.EC_TAGTYPE_UNKNOWN;
}
